using UnityEngine;
using UnityEditor;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var uss = Resources.Load<StyleSheet>("HUDTree/HudUI_kit");
        result.Log("Resources.Load<StyleSheet>(HUDTree/HudUI_kit) -> " + (uss == null ? "NULL" : "ok"));
        var overlay = Resources.Load<VisualTreeAsset>("HUDTree/HUDOverlay_kit");
        result.Log("Resources.Load<VisualTreeAsset>(HUDTree/HUDOverlay_kit) -> " + (overlay == null ? "NULL" : "ok"));
        var hud = Resources.Load<VisualTreeAsset>("HUDTree/HudUI");
        result.Log("Resources.Load<VisualTreeAsset>(HUDTree/HudUI) [original] -> " + (hud == null ? "NULL" : "ok"));

        // Spot-check 2 atlas sprite sampling so we know the kit art aligns
        // with the row offsets in HudUI_kit.uss at runtime.
        var vital = Resources.Load<Texture2D>("HUDTree/Atlases/Kit/vital_atlas_kit");
        if (vital != null)
        {
            // hover vs amber vs red aren't in the kit; vital atlas is plain icons.
            // Sample the upper-left cell (thirst) and confirm it's non-transparent.
            var c = vital.GetPixel(64, 64);
            result.Log("vital_atlas_kit[64,64] = " + c);
        }
    }
}
